function deriveAttention(events: readonly AttentionEvent[], revision: bigint): AttentionProjection { if (events.length === 0) refuse("attention events missing"); let selected = events[0]!; let unread = 0n; let source_revision = 0n; for (const event of events) { if (event.origin.revision > revision) refuse("attention is newer than snapshot"); unread += event.unread; if (unread > BigInt(MAX_REVIEW_UNREAD)) refuse("unread count too large"); if (event.origin.revision > source_revision) source_revision = event.origin.revision; const eventPrecedence = attentionPrecedence(event.reason); const selectedPrecedence = attentionPrecedence(selected.reason); if (eventPrecedence > selectedPrecedence || (eventPrecedence === selectedPrecedence && (event.origin.revision > selected.origin.revision || (event.origin.revision === selected.origin.revision && reasonOrder(event.reason) < reasonOrder(selected.reason))))) selected = event; } return {reason: selected.reason, source_revision, state: attentionState(selected.reason), unread}; }
