function validateAnchorInFiles(anchor: ReviewAnchor, files: readonly ReviewFile[]): void { const file = files.find((entry) => entry.id === anchor.file_id); const hunk = file?.hunks.find((entry) => entry.id === anchor.hunk_id); if (hunk === undefined) refuse("comment anchor is not in snapshot"); const start = anchor.side === "old" ? hunk.old_start : hunk.new_start; const lines = anchor.side === "old" ? hunk.old_lines : hunk.new_lines; if (lines === 0n || anchor.line < start || anchor.line >= start + lines) refuse("comment anchor line is outside hunk"); }
