export function validateReviewActionReceipt(value: unknown): ReviewActionReceipt { const v = object(value, ["action_id", "actor", "current_revision", "idempotency_key", "outcome", "platform_version", "receipt_id", "reconciliation", "revision", "schema"]); if (v.schema !== PLATFORM_REVIEW_SCHEMA_V1 || v.platform_version !== 2n) invalid("review requires Platform v2"); const outcome = enumeration(v.outcome, enums.outcome, "receipt outcome"); const revision = optionalRevision(v.revision); const current_revision = optionalRevision(v.current_revision); const reconciliation = enumeration(v.reconciliation, enums.reconciliation, "reconciliation"); const valid = outcome === "accepted" ? revision === null && current_revision === null && reconciliation === "poll_receipt" : outcome === "completed" ? revision !== null && current_revision === null && reconciliation === "final" : outcome === "refused" ? revision === null && current_revision === null && reconciliation === "final" : outcome === "conflict" ? revision === null && current_revision !== null && reconciliation === "final" : revision === null && current_revision === null && reconciliation === "poll_receipt"; if (!valid) refuse("receipt outcome is incoherent"); return {action_id: bounded(v.action_id, MAX_REVIEW_FIELD_BYTES, "action id"), actor: bounded(v.actor, MAX_REVIEW_FIELD_BYTES, "actor"), current_revision, idempotency_key: bounded(v.idempotency_key, MAX_REVIEW_FIELD_BYTES, "idempotency key"), outcome, platform_version: 2n, receipt_id: bounded(v.receipt_id, MAX_REVIEW_FIELD_BYTES, "receipt id"), reconciliation, revision, schema: PLATFORM_REVIEW_SCHEMA_V1}; }

function json(value: unknown): JsonValue { if (value === null) return {kind: "null"}; if (typeof value === "boolean") return {kind: "bool", value}; if (typeof value === "bigint") return {kind: "integer", value}; if (typeof value === "string") return {kind: "string", value}; if (Array.isArray(value)) return {kind: "array", items: value.map(json)}; if (typeof value === "object") return {kind: "object", entries: Object.entries(value as Readonly<Record<string, unknown>>).map(([key, entry]) => [key, json(entry)] as const)}; throw new ValidationError("review", "unsupported JSON value"); }
