export function encodeReviewSnapshot(value: unknown): Uint8Array { return encoded(validateReviewSnapshot(value), MAX_REVIEW_SNAPSHOT_CANONICAL_BYTES); }
export function decodeReviewSnapshot(payload: Uint8Array): ReviewSnapshot { return validateReviewSnapshot(decoded(payload, MAX_REVIEW_SNAPSHOT_CANONICAL_BYTES)); }
export function encodeReviewActionRequest(value: unknown): Uint8Array { return encoded(validateReviewActionRequest(value), MAX_REVIEW_ACTION_CANONICAL_BYTES); }
export function decodeReviewActionRequest(payload: Uint8Array): ReviewActionRequest { return validateReviewActionRequest(decoded(payload, MAX_REVIEW_ACTION_CANONICAL_BYTES)); }
export function encodeReviewActionReceipt(value: unknown): Uint8Array { return encoded(validateReviewActionReceipt(value), MAX_REVIEW_RECEIPT_CANONICAL_BYTES); }
export function decodeReviewActionReceipt(payload: Uint8Array): ReviewActionReceipt { return validateReviewActionReceipt(decoded(payload, MAX_REVIEW_RECEIPT_CANONICAL_BYTES)); }
